object ThusoIQData {
    /* One source, and it is labelled a simulator. There is no device in this product:
       `devices` is a simulated capability, and a sample that did not say where it came from
       could be mistaken for one that did. */
    val sampleSources = listOf("simulator")

    /* The four headings are not written down here. They are records.json's, they already
       appear on the consultation form in all three apps, and a second list would be the copy
       that drifts. `mustBe` is 4 because two of the refusals below say the word ‘four’ out
       loud, so the day somebody adds a fifth section the generator fails rather than the
       sentence quietly becoming a lie. */
    val soapKeys = listOf("subjective", "objective", "assessment", "plan")

    /* The record types in packages/catalog/records.json that this kernel writes to. It is a
       list of ids and not a list of definitions: what each one is, which area it belongs to
       and who may open it are that file's, and the generator fails if a name here is not one
       of them. */
    val recordTypes = listOf("appointment", "home-visit", "consultation", "diagnosis", "prescription", "dispense", "vitals", "audit")

    /* Named rather than invented. Every one of these is simulated or absent in
       packages/catalog/capabilities.json, and this kernel is the simulation — a sandbox in
       memory, seeded with three fictional patients, holding nothing when the tab closes. */
    val capabilities = listOf("booking", "clinical-records", "dispensing", "devices")

    /* Every number the kernel enforces, in one place, each with the reason it is that number
       and not another. Two of the refusal sentences are filled from these values rather than
       repeating them, so a bound cannot be changed without the sentence changing with it. */
    /** minutes */
    const val appointmentMinutesMin = 10
    /** minutes */
    const val appointmentMinutesMax = 180
    /** characters */
    const val noteCharactersMax = 5000
    /** units of a medicine */
    const val quantityMin = 1
    /** units of a medicine */
    const val quantityMax = 1000
    /** milliseconds */
    const val futureToleranceMsMax = 60000L
    /** characters */
    const val idempotencyKeyCharactersMax = 200
    /** milliseconds */
    const val sampleStaleAfterMsMax = 300000L
    /** samples */
    const val sampleBufferMax = 500
    /** events */
    const val auditBufferMax = 1000

    /* No engine reads a sample and concludes anything. A heart rate does not raise an
       assessment, does not escalate a visit and does not appear in a diagnosis unless a
       clinician typed it there as evidence under their own name. */
    /* No engine here interprets a clinical value, scores a patient, ranks a queue, suggests a
       diagnosis, or lets one person perform two of the three dispensing acts. There is no
       override, no force flag and no administrative path that skips a check — an operator who
       needs one of these refusals lifted needs a clinician, not a button. */

    fun refusal(id: String) = thusoIQRefusals.firstOrNull { it.id == id }
    fun fieldLabel(id: String) = thusoIQFieldLabels.firstOrNull { it.id == id }?.label
    fun unit(metric: String) = thusoIQMetrics.firstOrNull { it.id == metric }?.unit
    fun transitionsFrom(state: String) = thusoIQAppointmentTransitions[state] ?: emptyList()

    /**
     * The sentence with its placeholders filled, exactly as the web kernel fills them. A refusal is
     * looked up first, so a missing id is null here rather than an empty sentence in front of
     * somebody being told no.
     */
    fun fill(refusal: ThusoIQRefusal, fills: Map<String, String> = emptyMap()): String =
        refusal.fills.fold(refusal.sentence) { text, token -> text.replace("{$token}", fills[token] ?: "") }

    /**
     * Grouped by hand rather than by locale, so a sentence a patient reads does not change shape
     * with the device's region setting. Bounds are positive whole numbers — the generator throws
     * otherwise — so there is no sign to carry.
     */
    fun grouped(value: Int): String {
        val digits = value.toString()
        return buildString {
            digits.forEachIndexed { index, character ->
                if (index > 0 && (digits.length - index) % 3 == 0) append(',')
                append(character)
            }
        }
    }
}
